    ('696624d4-3f88-4175-a4cd-fd145d00174a'::uuid, 'card_description', 'Near the Ziggurat of Ur lay dozens of artifacts, centuries apart in age, set neatly side by side with clay labels: Ennigaldi-Nanna''s Museum, the earliest known public museum, circa 530 BCE.', 'The world''s earliest known public museum, dating to 530 BC. Curated by Princess Ennigaldi, daughter of the last Babylonian king, near the Ziggurat of Ur.', 'teaser-card-s023-rollback:696624d4-3f88-4175-a4cd-fd145d00174a:card_description', 'rollback of teaser-card-s023: card_description "The world''s earliest known public museum, dating to 530 BC. Curated by Princess Ennigaldi, daughter of the last Babylonian king, near the Ziggurat of Ur." restored on Ennigaldi-Nanna''s Museum', '7484f35c92a5a39a71f69399464e4db4817657d2275f31df5828a4dde361bb71|bc3cabfbbf4e7d1200a7d901f52ec36b7135768fed7a7d6d6c6faf3277074000|bc3cabfbbf4e7d1200a7d901f52ec36b7135768fed7a7d6d6c6faf3277074000', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Near the Ziggurat of Ur lay dozens of artifacts, centuries apart in age, set neatly side by side with clay labels: Ennigaldi-Nanna''s Museum, the earliest known public museum, circa 530 BCE."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the site lies near the Ziggurat of Ur [S4]; dozens of artifacts were found there [S6]; the artifacts'' ages differed by centuries [S6]; the artifacts were set neatly side by side [S6]; the artifacts were accompanied by clay labels [S7]; the site is Ennigaldi-Nanna''s Museum [S1]; it is the earliest known public museum [S1]; it dates to circa 530 BCE [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-037 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Ennigaldi-Nanna''s Museum is a museum [SUPPORTED: https://en.wikipedia.org/wiki/Ennigaldi-Nanna%27s_museum]; It is the earliest known public museum [SUPPORTED: https://en.wikipedia.org/wiki/Ennigaldi-Nanna%27s_museum]; The museum dates to circa 530 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Ennigaldi-Nanna%27s_museum]; The museum lay near the Ziggurat of Ur [SUPPORTED: https://en.wikipedia.org/wiki/Ennigaldi-Nanna%27s_museum]; The museum was at Ur, in Iraq [SUPPORTED: https://en.wikipedia.org/wiki/Ennigaldi-Nanna%27s_museum]; Dozens of artifacts lay there [SUPPORTED: https://en.wikipedia.org/wiki/Ennigaldi-Nanna%27s_museum]; The artifacts were centuries apart in age [SUPPORTED: https://en.wikipedia.org/wiki/Ennigaldi-Nanna%27s_museum]; The artifacts were set neatly side by side [SUPPORTED: https://en.wikipedia.org/wiki/Ennigaldi-Nanna%27s_museum]; The artifacts were set out with clay labels [SUPPORTED: https://en.wikipedia.org/wiki/Ennigaldi-Nanna%27s_museum]"}]'::jsonb),
    ('6b2cc1ad-eb68-4f1d-9181-42cc5f84cda0'::uuid, 'card_description', 'Work on the Athens to Thessaloniki railway uncovered an ancient farmhouse at Tria Platania, where a study of olive remains traced how oil was made from the fourth to the second century BC.', NULL, 'teaser-card-s023-rollback:6b2cc1ad-eb68-4f1d-9181-42cc5f84cda0:card_description', 'rollback of teaser-card-s023: card_description None restored on Tria Platania', 'e729babc001284cced2990879548af1ce683ee27f9387a3d8376b3a5242bf43f|60fa28ad18a7e0bbae23bff25862bcb67707ba7256982d21ab2bfe9b8e948a7a|60fa28ad18a7e0bbae23bff25862bcb67707ba7256982d21ab2bfe9b8e948a7a', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Work on the Athens to Thessaloniki railway uncovered an ancient farmhouse at Tria Platania, where a study of olive remains traced how oil was made from the fourth to the second century BC."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "construction work on the Athens-Thessaloniki railway line uncovered the remains [S1]; the remains are of an ancient farmhouse [S1]; the farmhouse is at Tria Platania [S1]; a study examined olive remains [S3]; the study was about how olive oil was produced [S3]; the period studied is the fourth to the second century BC [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-037 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Tria Platania, Greece, is an ancient farmhouse site [SUPPORTED: https://en.wikipedia.org/wiki/Tria_Platania]; The farmhouse was uncovered at Tria Platania [SUPPORTED: https://en.wikipedia.org/wiki/Tria_Platania]; Construction work on a railway uncovered the farmhouse [SUPPORTED: https://en.wikipedia.org/wiki/Tria_Platania]; The railway is the Athens to Thessaloniki line [SUPPORTED: https://en.wikipedia.org/wiki/Tria_Platania]; A study of olive remains was made [SUPPORTED: https://en.wikipedia.org/wiki/Tria_Platania]; The study traced how olive oil was made [SUPPORTED: https://link.springer.com/article/10.1007/s00334-008-0155-9]; The oil production traced runs from the fourth to the second century BC [SUPPORTED: https://en.wikipedia.org/wiki/Tria_Platania]"}]'::jsonb),
    ('6cc29702-81c5-4a0a-bc3e-a62de9545b3a'::uuid, 'card_description', 'In the rain forest of Manú National Park, the rock face of Pusharo bears deeply incised heart-shaped faces, spirals, zigzags, suns and shapes that defy verbal description.', 'The site is made up of an array of deeply incised rock carvings that cover up to a height of 9 feet, a perpendicular rock face that is over 100 feet long and 75 feet high.', 'teaser-card-s023-rollback:6cc29702-81c5-4a0a-bc3e-a62de9545b3a:card_description', 'rollback of teaser-card-s023: card_description ''The site is made up of an array of deeply incised rock carvings that cover up to a height of 9 feet, a perpendicular rock face that is over 100 feet long and 75 feet high.'' restored on Pusharo', 'f773f6e6e7fc0f05ce62cc89912e99c9ab1f5a5157f71eac1e3e87f99e62525b|cc65e4e6066653edb70210b64401b03c14088e5a88ac4e350bd02ec6aae177f2|cc65e4e6066653edb70210b64401b03c14088e5a88ac4e350bd02ec6aae177f2', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In the rain forest of Manú National Park, the rock face of Pusharo bears deeply incised heart-shaped faces, spirals, zigzags, suns and shapes that defy verbal description."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Pusharo is in Manu National Park [S1]; the park is rain forest [S1]; Pusharo is a rock face bearing carvings [S5]; the carvings are deeply incised [S5]; the carvings include heart-shaped faces, spirals, zigzags and suns [S7]; some of the shapes defy verbal description [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-037 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Pusharo is a rock art (petroglyph) site [SUPPORTED: https://en.wikipedia.org/wiki/Pusharo]; Pusharo lies in Manú National Park, Peru [SUPPORTED: https://en.wikipedia.org/wiki/Pusharo]; The park is rain forest [SUPPORTED: https://en.wikipedia.org/wiki/Pusharo]; The carvings are on a rock face [SUPPORTED: https://en.wikipedia.org/wiki/Pusharo]; The carvings are deeply incised [SUPPORTED: https://en.wikipedia.org/wiki/Pusharo]; The petroglyphs include heart-shaped faces [SUPPORTED: https://en.wikipedia.org/wiki/Pusharo]; The petroglyphs include spirals and zigzags [SUPPORTED: https://en.wikipedia.org/wiki/Pusharo]; The petroglyphs include suns [SUPPORTED: https://en.wikipedia.org/wiki/Pusharo]; Some shapes defy verbal description [SUPPORTED: https://en.wikipedia.org/wiki/Pusharo]"}]'::jsonb),
    ('6cf9cf72-ba27-4843-bbd4-e9acfabec124'::uuid, 'card_description', NULL, 'At 4,089 meters near Cusco, Wanakawri was the most sacred wak''a in the Inca religious system — central to founding myths and visited in major state rituals from 1438 until the Spanish conquest.', 'teaser-card-s023-rollback:6cf9cf72-ba27-4843-bbd4-e9acfabec124:card_description', 'rollback of teaser-card-s023: card_description "At 4,089 meters near Cusco, Wanakawri was the most sacred wak''a in the Inca religious system — central to founding myths and visited in major state rituals from 1438 until the Spanish conquest." restored on Wanakawri, Cusco', '||acbe919e8cb034bda965a112798cfe32c2ddd57ece20c41e3b0d9dfb7132309c', '[{"source": "lane WB run wb-ws-2026-09-27-05: unproven-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The web check could not prove: Wanakawri is a legendary mountain with archaeological remains (an archaeological site and a legendary mountain) near Cusco, Peru; The web check could not prove: Wanakawri is a mountain with archaeological remains near Cusco, Peru"}]'::jsonb),
    ('6d28ceb7-10be-442f-be2e-cab319d32763'::uuid, 'card_description', 'In a pasture by the upper Lamorna River, Brane Barrow, a Neolithic entrance grave ringed by granite blocks, shelters a stone-lined chamber roofed with two capstones. A third was removed.', 'A Neolithic entrance grave considered one of the smallest and best-preserved in Britain. The circular mound is built of rubble and soil, typical of the Scillonian entrance type.', 'teaser-card-s023-rollback:6d28ceb7-10be-442f-be2e-cab319d32763:card_description', 'rollback of teaser-card-s023: card_description ''A Neolithic entrance grave considered one of the smallest and best-preserved in Britain. The circular mound is built of rubble and soil, typical of the Scillonian entrance type.'' restored on Brane Barrow', '168b9c82efd5b407aa2ff1468cebc44853fcdd3cf232cc2f16c3e06e4f699784|732f36f3c54b2d46156f6945e3868b5204190ba32d7f14d4e31a40030236a79a|732f36f3c54b2d46156f6945e3868b5204190ba32d7f14d4e31a40030236a79a', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In a pasture by the upper Lamorna River, Brane Barrow, a Neolithic entrance grave ringed by granite blocks, shelters a stone-lined chamber roofed with two capstones. A third was removed."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Brane Barrow is in a pasture [S4]; the pasture is close to the upper Lamorna River [S4]; Brane Barrow is a Neolithic entrance grave [S1]; it is ringed by granite blocks [S6]; it contains a stone-lined chamber [S7]; the chamber is roofed with two capstones [S8]; a third capstone was removed [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-038 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Brane Barrow is an entrance grave (burial monument) in Cornwall, England [SUPPORTED: https://en.wikipedia.org/wiki/Brane_Barrow]; The entrance grave is Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Brane_Barrow]; It lies in a pasture [SUPPORTED: https://en.wikipedia.org/wiki/Brane_Barrow]; The pasture is by the upper Lamorna River [SUPPORTED: https://en.wikipedia.org/wiki/Brane_Barrow]; The mound is ringed by granite blocks [SUPPORTED: https://en.wikipedia.org/wiki/Brane_Barrow]; It shelters a stone-lined chamber [SUPPORTED: https://en.wikipedia.org/wiki/Brane_Barrow]; The chamber is roofed with two capstones [SUPPORTED: https://en.wikipedia.org/wiki/Brane_Barrow]; A third capstone was removed [SUPPORTED: https://en.wikipedia.org/wiki/Brane_Barrow]"}]'::jsonb),
    ('6da4f22e-a5a5-49f2-abb2-b6576e131746'::uuid, 'card_description', 'On a north-facing ridge in Cornwall, large stones enclose the damaged chamber of Pawton Quoit, a Neolithic portal dolmen recorded as the Druid''s Altar on the Ordnance Survey map in 1813.', 'A Neolithic portal dolmen from 3500-2600 BC with a long burial mound. It sits on a north-facing ridge looking out over a tributary of the River Camel.', 'teaser-card-s023-rollback:6da4f22e-a5a5-49f2-abb2-b6576e131746:card_description', 'rollback of teaser-card-s023: card_description ''A Neolithic portal dolmen from 3500-2600 BC with a long burial mound. It sits on a north-facing ridge looking out over a tributary of the River Camel.'' restored on Pawton Quoit', '053a551734da7d4870f020fd94bc53932e2d6e9f973db5d850c046829ffb2a78|0b47afb20ae3d29061ae00675949b5dc88d872597dc9c45cb9802bb30aa10bea|0b47afb20ae3d29061ae00675949b5dc88d872597dc9c45cb9802bb30aa10bea', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On a north-facing ridge in Cornwall, large stones enclose the damaged chamber of Pawton Quoit, a Neolithic portal dolmen recorded as the Druid''s Altar on the Ordnance Survey map in 1813."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Pawton Quoit sits on a north-facing ridge [S3]; it is in Cornwall [S2]; large stones enclose its chamber [S7]; the chamber is damaged [S6]; Pawton Quoit is a Neolithic portal dolmen [S1]; it was recorded as the Druid''s Altar on the Ordnance Survey map [S8]; that record dates from 1813 [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-038 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Pawton Quoit is a portal dolmen (burial monument) [SUPPORTED: https://en.wikipedia.org/wiki/Pawton_Quoit]; Pawton Quoit is Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Pawton_Quoit]; It is in Cornwall [SUPPORTED: https://en.wikipedia.org/wiki/Pawton_Quoit]; It stands on a north-facing ridge [SUPPORTED: https://en.wikipedia.org/wiki/Pawton_Quoit]; Large stones enclose the chamber [SUPPORTED: https://en.wikipedia.org/wiki/Pawton_Quoit]; The chamber is damaged [SUPPORTED: https://en.wikipedia.org/wiki/Pawton_Quoit]; It was recorded as the Druid''s Altar [SUPPORTED: https://en.wikipedia.org/wiki/Pawton_Quoit]; The record was on the Ordnance Survey map [SUPPORTED: https://en.wikipedia.org/wiki/Pawton_Quoit]; The Ordnance Survey record dates to 1813 [SUPPORTED: https://en.wikipedia.org/wiki/Pawton_Quoit]"}]'::jsonb),
    ('6e49927e-99cd-480d-8474-4da41b51ae46'::uuid, 'card_description', 'On Woodhouse Crag, Ilkley Moor, the Swastika Stone bears a double-outlined swastika with a cup mark in each curved arm: the only one of its kind known in Britain, not verifiably dated.', 'A carved swastika-like design from around 3300 BC—millennia before the symbol gained modern associations. It closely matches a motif found in Scandinavia.', 'teaser-card-s023-rollback:6e49927e-99cd-480d-8474-4da41b51ae46:card_description', 'rollback of teaser-card-s023: card_description ''A carved swastika-like design from around 3300 BC—millennia before the symbol gained modern associations. It closely matches a motif found in Scandinavia.'' restored on Swastika Stone', '01486058e38c4e985fe786dec53f2108a2e230aebbfc6d0450553717183742c7|18099339e4e601c42ff6490f4659dbc59b164ea3fb4f14c14b17ed08a944483a|18099339e4e601c42ff6490f4659dbc59b164ea3fb4f14c14b17ed08a944483a', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On Woodhouse Crag, Ilkley Moor, the Swastika Stone bears a double-outlined swastika with a cup mark in each curved arm: the only one of its kind known in Britain, not verifiably dated."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Swastika Stone is on Woodhouse Crag [S1]; Woodhouse Crag is on Ilkley Moor [S1]; the stone bears a swastika [S1]; the swastika has a double outline [S3]; the swastika has curved arms [S3]; each curved arm encloses a cup mark [S3]; it is the only one of its kind known in Britain [S2]; the stone has not been verifiably dated [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-038 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Swastika Stone is a stone bearing a swastika [SUPPORTED: https://en.wikipedia.org/wiki/Swastika_Stone]; It is on Woodhouse Crag [SUPPORTED: https://en.wikipedia.org/wiki/Swastika_Stone]; Woodhouse Crag is on Ilkley Moor [SUPPORTED: https://en.wikipedia.org/wiki/Swastika_Stone]; The swastika has a double outline [SUPPORTED: https://en.wikipedia.org/wiki/Swastika_Stone]; The swastika has curved arms [SUPPORTED: https://en.wikipedia.org/wiki/Swastika_Stone]; There is a cup mark in each curved arm [SUPPORTED: http://www.stone-circles.org.uk/stone/swastikastone.htm]; It is the only one of its kind known in Britain [SUPPORTED: https://en.wikipedia.org/wiki/Swastika_Stone]; It is not verifiably dated [SUPPORTED: https://en.wikipedia.org/wiki/Swastika_Stone]"}]'::jsonb),
    ('6e836171-0fc6-44e3-a2af-672a7b740d5d'::uuid, 'card_description', 'Near Addington in Kent, the sarsen chamber of Chestnuts Long Barrow held cremated and inhumed remains of at least nine or ten people, with arrow heads, pottery sherds and a clay pendant.', 'In the 12th or 13th century, the chamber was dug into and heavily damaged, either by treasure hunters or iconoclastic Christians.', 'teaser-card-s023-rollback:6e836171-0fc6-44e3-a2af-672a7b740d5d:card_description', 'rollback of teaser-card-s023: card_description ''In the 12th or 13th century, the chamber was dug into and heavily damaged, either by treasure hunters or iconoclastic Christians.'' restored on Chestnuts Long Barrow', '0971d0e0fad1827ad698095790aa57bcbec9ee2d72f76ef6baaf7c30c7374f48|7472f43ad5f7348f3f90a3d905314fb401d0d14e06c337f5c7e80fea80601b00|7472f43ad5f7348f3f90a3d905314fb401d0d14e06c337f5c7e80fea80601b00', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Near Addington in Kent, the sarsen chamber of Chestnuts Long Barrow held cremated and inhumed remains of at least nine or ten people, with arrow heads, pottery sherds and a clay pendant."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Chestnuts Long Barrow is near Addington [S1]; it is in Kent [S1]; the barrow has a chamber built of sarsen [S3]; the chamber held both cremated and inhumed human remains [S4]; the remains represent at least nine or ten individuals [S4]; arrow heads were found with the remains [S5]; pottery sherds were found with the remains [S5]; a clay pendant was found with the remains [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-038 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Chestnuts Long Barrow is a chambered long barrow [SUPPORTED: https://en.wikipedia.org/wiki/Chestnuts_Long_Barrow]; It is near Addington [SUPPORTED: https://en.wikipedia.org/wiki/Chestnuts_Long_Barrow]; Addington is in Kent [SUPPORTED: https://en.wikipedia.org/wiki/Chestnuts_Long_Barrow]; The chamber is built of sarsen [SUPPORTED: https://en.wikipedia.org/wiki/Chestnuts_Long_Barrow]; The chamber held cremated remains [SUPPORTED: https://en.wikipedia.org/wiki/Chestnuts_Long_Barrow]; The chamber held inhumed remains [SUPPORTED: https://en.wikipedia.org/wiki/Chestnuts_Long_Barrow]; The remains represent at least nine or ten people [SUPPORTED: https://en.wikipedia.org/wiki/Chestnuts_Long_Barrow]; Arrow heads were found with the remains [SUPPORTED: https://en.wikipedia.org/wiki/Chestnuts_Long_Barrow]; Pottery sherds were found with the remains [SUPPORTED: https://en.wikipedia.org/wiki/Chestnuts_Long_Barrow]; A clay pendant was found with the remains [SUPPORTED: https://en.wikipedia.org/wiki/Chestnuts_Long_Barrow]"}]'::jsonb),
    ('6eec508c-8458-4758-aba2-5745dd9fe089'::uuid, 'card_description', 'Approximately 500 terraces, some 6 metres high, follow the contours of a mountain ridge in the Sacred Valley, where the Inca Complex at Písac keeps watchtowers and a ceremonial centre.', 'An Inca complex along mountain ridges above the Sacred Valley, with agricultural terraces, watchtowers, guard posts, and a major ceremonial center.', 'teaser-card-s023-rollback:6eec508c-8458-4758-aba2-5745dd9fe089:card_description', 'rollback of teaser-card-s023: card_description ''An Inca complex along mountain ridges above the Sacred Valley, with agricultural terraces, watchtowers, guard posts, and a major ceremonial center.'' restored on Inca Complex at Písac', 'e6bfd72d78776e17375abf539427d48bb2fa9917476f426dbfab0fddc07c0a4e|0355ce0f8d6ace4ce4da81200b1df38459daca08e6e79c38565b48d69f4b3fc8|0355ce0f8d6ace4ce4da81200b1df38459daca08e6e79c38565b48d69f4b3fc8', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Approximately 500 terraces, some 6 metres high, follow the contours of a mountain ridge in the Sacred Valley, where the Inca Complex at Písac keeps watchtowers and a ceremonial centre."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "there are approximately 500 terraces [S6]; some terraces are 6 metres high [S6]; the terraces follow the contours of the hillside [S6]; the complex lies along a mountain ridge [S1]; it is in the Sacred Valley [S1]; the Inca Complex at Pisac includes watchtowers [S1]; the complex includes a ceremonial centre [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-039 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Inca Complex at Písac is a large Inca complex of agricultural terraces, residences, guard posts, watchtowers and a ceremonial centre on a mountain ridge in the Sacred Valley of Peru (central claim: what and where) [SUPPORTED: https://en.wikipedia.org/wiki/Inca_complex_at_P%C3%ADsac]; The site has approximately 500 terraces [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Inca_complex_at_P%C3%ADsac]; Some of the terraces are about 6 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Inca_complex_at_P%C3%ADsac]; The terraces follow the contours of the mountain ridge/hillside [SUPPORTED: https://en.wikipedia.org/wiki/Inca_complex_at_P%C3%ADsac]; The site has watchtowers [SUPPORTED: https://en.wikipedia.org/wiki/Inca_complex_at_P%C3%ADsac]; The site has a ceremonial centre [SUPPORTED: https://en.wikipedia.org/wiki/Inca_complex_at_P%C3%ADsac]; The site lies in the Sacred Valley (Peru) [SUPPORTED: https://en.wikipedia.org/wiki/Inca_complex_at_P%C3%ADsac]"}]'::jsonb),
    ('6fa3017d-6545-48c6-b54b-c041b9f860b8'::uuid, 'card_description', 'On a mound bearing the remains of a big ancient city in Sindh stands Sudheran-Jo-Thul, a Buddhist stupa south of Hyderabad that locals know as the Tower of Sudheran.', '450 BC–1200 AD Buddhist stupa on a mound near Tando Muhammad Khan. Locally called the Tower of Sudheran — believed by some to be a cinerary stupa containing the ashes of the dead.', 'teaser-card-s023-rollback:6fa3017d-6545-48c6-b54b-c041b9f860b8:card_description', 'rollback of teaser-card-s023: card_description ''450 BC–1200 AD Buddhist stupa on a mound near Tando Muhammad Khan. Locally called the Tower of Sudheran — believed by some to be a cinerary stupa containing the ashes of the dead.'' restored on Sudheran-Jo-Thul', 'ccf6d7839d3afe55e4dd00e75cb766cd3cddf9ab093423586c767ec5936bc6f7|3b3774d274b40c67da3616642930106462263c59ec636dbf714aa5262e2768f2|3b3774d274b40c67da3616642930106462263c59ec636dbf714aa5262e2768f2', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On a mound bearing the remains of a big ancient city in Sindh stands Sudheran-Jo-Thul, a Buddhist stupa south of Hyderabad that locals know as the Tower of Sudheran."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Sudheran-Jo-Thul stands on a mound [S2]; the mound shows the remains of a big ancient city [S2]; it is in Sindh [S1]; Sudheran-Jo-Thul is a Buddhist stupa [S1]; it lies south of Hyderabad [S3]; locally it is known as the Tower of Sudheran [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-039 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Sudheran-Jo-Thul is a stupa (central claim: what kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Sudheran-Jo-Thul]; The stupa is Buddhist [SUPPORTED: https://en.wikipedia.org/wiki/Sudheran-Jo-Thul]; The site is in Sindh (Pakistan) [SUPPORTED: https://en.wikipedia.org/wiki/Sudheran-Jo-Thul]; The stupa stands on a mound [SUPPORTED: https://en.wikipedia.org/wiki/Sudheran-Jo-Thul]; The mound bears the remains of a big ancient city [SUPPORTED: https://en.wikipedia.org/wiki/Sudheran-Jo-Thul]; The stupa lies south of Hyderabad [SUPPORTED: https://en.wikipedia.org/wiki/Sudheran-Jo-Thul]; Locals know the stupa as the Tower of Sudheran [SUPPORTED: https://en.wikipedia.org/wiki/Sudheran-Jo-Thul]; The name of the stupa is Sudheran-Jo-Thul [SUPPORTED: https://en.wikipedia.org/wiki/Sudheran-Jo-Thul]"}]'::jsonb),
    ('6fa8cd4d-074f-4b88-9f98-95465b49c9ae'::uuid, 'card_description', 'At the base of a peninsula jutting into the Tyrrhenian Sea, Milazzo began as Greek Mylae, occupied before 648 BC, perhaps as early as 716 BC, and taken by the Athenians in 426 BC.', 'Settled from the Neolithic onward, Milazzo''s strategic peninsula was fortified by successive powers for millennia. Homer''s Odyssey may place Odysseus''s encounter with the Cyclops near this bay.', 'teaser-card-s023-rollback:6fa8cd4d-074f-4b88-9f98-95465b49c9ae:card_description', 'rollback of teaser-card-s023: card_description "Settled from the Neolithic onward, Milazzo''s strategic peninsula was fortified by successive powers for millennia. Homer''s Odyssey may place Odysseus''s encounter with the Cyclops near this bay." restored on Milazzo', '0e41e9ada01616b691cf06ae96353c07e14d83c02ada82fb34c0ed70f382ddea|1d0705247fb275d693067515c66d45074544d6c7c4930a00aed62d3350caa7bb|1d0705247fb275d693067515c66d45074544d6c7c4930a00aed62d3350caa7bb', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "At the base of a peninsula jutting into the Tyrrhenian Sea, Milazzo began as Greek Mylae, occupied before 648 BC, perhaps as early as 716 BC, and taken by the Athenians in 426 BC."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Milazzo is at the base of a peninsula [S4]; the peninsula juts into the Tyrrhenian Sea [S4]; Milazzo originated as the Greek Mylae [S2]; Mylae was occupied before 648 BC [S2]; Mylae was perhaps occupied as early as 716 BC (kept as a hedge) [S2]; it was taken by the Athenians in 426 BC [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-039 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Milazzo is a town/municipality in Sicily, Italy (central claim: what kind of place and where) [SUPPORTED: https://en.wikipedia.org/wiki/Milazzo]; Milazzo is located at the base of a peninsula [SUPPORTED: https://en.wikipedia.org/wiki/Milazzo]; The peninsula juts into the Tyrrhenian Sea [SUPPORTED: https://en.wikipedia.org/wiki/Milazzo]; Milazzo began as the Greek settlement Mylae [SUPPORTED: https://en.wikipedia.org/wiki/Milazzo]; Mylae was occupied before 648 BC [SUPPORTED: https://en.wikipedia.org/wiki/Milazzo]; Occupation perhaps as early as 716 BC [SUPPORTED: https://en.wikipedia.org/wiki/Milazzo]; Mylae was taken by the Athenians in 426 BC [SUPPORTED: https://en.wikipedia.org/wiki/Milazzo]"}]'::jsonb),
    ('72396ba8-bfa7-46e1-8abe-e06c76dbe570'::uuid, 'card_description', 'Beside the Petit Moulin river, Léon Péricard found the paintings of La Marche Cave in November 1937, and five years of study with Stephane Lwoff revealed etchings on more than 1,500 slabs.', 'A cave with 15,000-year-old engravings showing detailed human faces with individual features. These realistic portraits challenged the idea that Ice Age art was only abstract.', 'teaser-card-s023-rollback:72396ba8-bfa7-46e1-8abe-e06c76dbe570:card_description', 'rollback of teaser-card-s023: card_description ''A cave with 15,000-year-old engravings showing detailed human faces with individual features. These realistic portraits challenged the idea that Ice Age art was only abstract.'' restored on La Marche Cave', 'a63a97ea8cb359fb33ba78b7da563051c722bf15f4075917115176af1678016c|82a1416e6ce03d6dc67791187a4a6552bd9840fdb6574a886688573aadb62e2d|82a1416e6ce03d6dc67791187a4a6552bd9840fdb6574a886688573aadb62e2d', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Beside the Petit Moulin river, Léon Péricard found the paintings of La Marche Cave in November 1937, and five years of study with Stephane Lwoff revealed etchings on more than 1,500 slabs."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "La Marche Cave lies by the Petit Moulin river [S2]; Leon Pericard discovered the La Marche Cave paintings [S4]; the discovery was in November 1937 [S4]; Pericard studied the cave together with Stephane Lwoff [S5]; the study lasted five years [S5]; they found etchings on more than 1,500 slabs [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-039 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "La Marche Cave is a cave and archaeological site in France (Lussac-les-Châteaux, Vienne) with cave art [SUPPORTED: https://en.wikipedia.org/wiki/La_Marche_(cave)]; The cave lies beside the Petit Moulin river [SUPPORTED: https://en.wikipedia.org/wiki/La_Marche_(cave)]; Léon Péricard found the paintings of La Marche Cave [SUPPORTED: https://en.wikipedia.org/wiki/La_Marche_(cave)]; The discovery was in November 1937 [SUPPORTED: https://en.wikipedia.org/wiki/La_Marche_(cave)]; Péricard studied the caves with Stephane Lwoff for five years [SUPPORTED: https://en.wikipedia.org/wiki/La_Marche_(cave)]; The study revealed etchings on more than 1,500 slabs [SUPPORTED: https://en.wikipedia.org/wiki/La_Marche_(cave)]"}]'::jsonb),
    ('7268effd-38c0-4961-a203-561e19982b1f'::uuid, 'card_description', 'In the Cordillera Blanca rises Waraqayuq, a mountain about 4,600 metres high. On its northern slope, above the Walpish valley, lies an archaeological site that shares its name.', 'Archaeological site in the Cordillera Blanca at ~4,600 m in Chavin de Huantar District. Waraqayuq overlooks valleys that connected coastal and highland worlds in the Andes'' most storied range.', 'teaser-card-s023-rollback:7268effd-38c0-4961-a203-561e19982b1f:card_description', 'rollback of teaser-card-s023: card_description "Archaeological site in the Cordillera Blanca at ~4,600 m in Chavin de Huantar District. Waraqayuq overlooks valleys that connected coastal and highland worlds in the Andes'' most storied range." restored on Waraqayuq', '134b9edfe5a0a4402eb4145cc621a4c34dd2525de652e65594d0363a70528d91|e2ae80e3ef92ab73b2b5270cc446bbc50e253a55896f6c3d69d70028ca4f8a47|e2ae80e3ef92ab73b2b5270cc446bbc50e253a55896f6c3d69d70028ca4f8a47', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In the Cordillera Blanca rises Waraqayuq, a mountain about 4,600 metres high. On its northern slope, above the Walpish valley, lies an archaeological site that shares its name."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Waraqayuq is in the Cordillera Blanca [S1]; Waraqayuq is a mountain [S1]; the mountain is about 4,600 metres high [S1]; an archaeological site lies on its northern slope [S3]; the site lies above the Walpish valley [S3]; the archaeological site shares the mountain''s name [S1, S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-039 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Waraqayuq is a mountain with an archaeological site of the same name (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Waraqayuq]; The mountain rises in the Cordillera Blanca [SUPPORTED: https://en.wikipedia.org/wiki/Waraqayuq]; The site is in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Waraqayuq]; The mountain is about 4,600 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Waraqayuq]; An archaeological site shares the mountain''s name [SUPPORTED: https://en.wikipedia.org/wiki/Waraqayuq]; The archaeological site lies on the northern slope of the mountain [SUPPORTED: https://en.wikipedia.org/wiki/Waraqayuq]; The site is above the Walpish valley [SUPPORTED: https://en.wikipedia.org/wiki/Waraqayuq]"}]'::jsonb),
    ('72cd16e3-8fc7-49a6-8f6d-efc56c40508d'::uuid, 'card_description', 'On a gentle south-facing slope in the open moorland of Weardale lie the Crawley Edge Cairns: forty-two Bronze Age barrows and cairns, and among them, unusually, a cremation mound.', 'The Crawley Edge Cairns are a series of forty-two Bronze Age round barrows, cairns and clearance cairns located in a field in Crawleyside, near Stanhope, County Durham.', 'teaser-card-s023-rollback:72cd16e3-8fc7-49a6-8f6d-efc56c40508d:card_description', 'rollback of teaser-card-s023: card_description ''The Crawley Edge Cairns are a series of forty-two Bronze Age round barrows, cairns and clearance cairns located in a field in Crawleyside, near Stanhope, County Durham.'' restored on Crawley Edge Cairns', '6537a2f0e56381646d2228f0ec3fd49f553b5d4f107809458f0e32d6d5f6733a|4434133404364fff378af586ae3d4321a966475a9646df3ae9cdb575558ed6d9|4434133404364fff378af586ae3d4321a966475a9646df3ae9cdb575558ed6d9', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On a gentle south-facing slope in the open moorland of Weardale lie the Crawley Edge Cairns: forty-two Bronze Age barrows and cairns, and among them, unusually, a cremation mound."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the site lies on a gentle south-facing slope [S2]; it is in open moorland [S2]; it is in Weardale [S2]; the Crawley Edge Cairns number forty-two [S1]; they are Bronze Age [S1]; they are barrows and cairns [S1]; among them is, unusually, a cremation mound [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-040 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Crawley Edge Cairns is a Bronze Age cairn/barrow site in England [SUPPORTED: https://en.wikipedia.org/wiki/Crawley_Edge_Cairns]; There are forty-two barrows and cairns [SUPPORTED: https://en.wikipedia.org/wiki/Crawley_Edge_Cairns]; The barrows and cairns date to the Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Crawley_Edge_Cairns]; The site is in Weardale [SUPPORTED: https://en.wikipedia.org/wiki/Crawley_Edge_Cairns]; The slope is gentle and south-facing [SUPPORTED: https://en.wikipedia.org/wiki/Crawley_Edge_Cairns]; The setting is open moorland [SUPPORTED: https://en.wikipedia.org/wiki/Crawley_Edge_Cairns]; Among the cairns is, unusually, a cremation mound [SUPPORTED: https://en.wikipedia.org/wiki/Crawley_Edge_Cairns]"}]'::jsonb),
    ('73228e20-288b-42a1-9bbf-bcad94fecbbc'::uuid, 'card_description', 'Near an Iron Age residence and cemetery stands Aulanko Castle, an ancient hillfort in Hämeenlinna. When it was built is not known; it was demolished in the 13th century.', 'Aulanko Castle is an ancient hillfort located in Hämeenlinna, Kanta-Häme. An Iron Age residence and a cemetery are also located near the castle.', 'teaser-card-s023-rollback:73228e20-288b-42a1-9bbf-bcad94fecbbc:card_description', 'rollback of teaser-card-s023: card_description ''Aulanko Castle is an ancient hillfort located in Hämeenlinna, Kanta-Häme. An Iron Age residence and a cemetery are also located near the castle.'' restored on Aulanko Castle', 'd6c0248a317217fb8c00a603c6125dfd3651e850ff8182b79be74ceb5892b47b|915110581f449fa4e13913599838a35f166b6f0f014a60c7969a6aace463b5f5|915110581f449fa4e13913599838a35f166b6f0f014a60c7969a6aace463b5f5', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Near an Iron Age residence and cemetery stands Aulanko Castle, an ancient hillfort in Hämeenlinna. When it was built is not known; it was demolished in the 13th century."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "an Iron Age residence and a cemetery lie near Aulanko Castle [S2]; Aulanko Castle is an ancient hillfort [S1]; it is in Hämeenlinna [S1]; it is not known when it was built [S3]; it was demolished in the 13th century [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-040 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Aulanko Castle is an ancient hillfort in Hämeenlinna [SUPPORTED: https://en.wikipedia.org/wiki/Aulanko_Castle]; An Iron Age residence is near the castle [SUPPORTED: https://en.wikipedia.org/wiki/Aulanko_Castle]; A cemetery is near the castle [SUPPORTED: https://en.wikipedia.org/wiki/Aulanko_Castle]; Construction date is unknown [SUPPORTED: https://en.wikipedia.org/wiki/Aulanko_Castle]; The site is an ancient hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Aulanko_Castle]; It was demolished in the 13th century [SUPPORTED: https://en.wikipedia.org/wiki/Aulanko_Castle]"}]'::jsonb),
    ('733f1f39-ab36-45cd-ba98-e37af64ad816'::uuid, 'card_description', 'Geophysical surveys of the valley settlement of Amiternum revealed a forum, basilica, baths, theater and amphitheater. Once a Sabine city, it was defeated by the Romans in 293 BC.', 'An ancient Sabine city that produced the historian Sallust. Its amphitheatre, aqueduct, and theatre still stand despite 2,500 years of earthquakes.', 'teaser-card-s023-rollback:733f1f39-ab36-45cd-ba98-e37af64ad816:card_description', 'rollback of teaser-card-s023: card_description ''An ancient Sabine city that produced the historian Sallust. Its amphitheatre, aqueduct, and theatre still stand despite 2,500 years of earthquakes.'' restored on Amiternum', 'b0d231778e753903cea8d408e97f04391c6fc58be2d48baf8fc5d436657d542b|3dade78b857481509dcbac2b78a3bda8ccbb4e267325a40c65d85f3dc7407b6e|3dade78b857481509dcbac2b78a3bda8ccbb4e267325a40c65d85f3dc7407b6e', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Geophysical surveys of the valley settlement of Amiternum revealed a forum, basilica, baths, theater and amphitheater. Once a Sabine city, it was defeated by the Romans in 293 BC."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "geophysical surveys were made of Amiternum''s valley settlement [S7]; the surveys revealed a forum, basilica, baths, theater and amphitheater [S7]; Amiternum was once a Sabine city [S1]; it was defeated by the Romans in 293 BC [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-040 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Amiternum was a valley settlement (ancient city) in Italy [SUPPORTED: https://en.wikipedia.org/wiki/Amiternum]; Geophysical surveys revealed a forum, basilica, baths, theater and amphitheater in the valley settlement [SUPPORTED: https://en.wikipedia.org/wiki/Amiternum]; It was once a Sabine city [SUPPORTED: https://en.wikipedia.org/wiki/Amiternum]; It was defeated by the Romans in 293 BC [SUPPORTED: https://en.wikipedia.org/wiki/Amiternum]"}]'::jsonb),
    ('73577152-2aef-4a45-9668-b0404238695b'::uuid, 'card_description', 'On the Opuntian Gulf lay Halae, a town of ancient Locris that probably took its name from salt springs still found nearby. Some ruins remain near the church of St. John.', 'Ancient Locrian town on the Opuntian Gulf, noted by Pausanias and Strabo. It likely took its name from nearby salt springs — ruins survive near the modern village of Theologos.', 'teaser-card-s023-rollback:73577152-2aef-4a45-9668-b0404238695b:card_description', 'rollback of teaser-card-s023: card_description ''Ancient Locrian town on the Opuntian Gulf, noted by Pausanias and Strabo. It likely took its name from nearby salt springs — ruins survive near the modern village of Theologos.'' restored on Halae', 'af079518287273f4b3e3a2d6475f66c0ab0b58994e4f0f1b0a6d915b14e907ae|b30a8df8c053859ac558e8863251b4612e879a0ae7e2ac7c79542c398567dca0|b30a8df8c053859ac558e8863251b4612e879a0ae7e2ac7c79542c398567dca0', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On the Opuntian Gulf lay Halae, a town of ancient Locris that probably took its name from salt springs still found nearby. Some ruins remain near the church of St. John."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Halae lay on the Opuntian Gulf [S1]; Halae was a town of ancient Locris [S1]; it probably took its name from salt springs [S3]; the salt springs are still found nearby [S3]; some ruins remain near the church of St. John [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-040 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Halae was a town of ancient Locris on the Opuntian Gulf [SUPPORTED: https://en.wikipedia.org/wiki/Halae]; Halae belonged to ancient Locris [SUPPORTED: https://en.wikipedia.org/wiki/Halae]; It probably took its name from salt springs [SUPPORTED: https://en.wikipedia.org/wiki/Halae]; The salt springs are still found nearby [SUPPORTED: https://en.wikipedia.org/wiki/Halae]; Some ruins remain near the church of St. John [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Halae]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 100;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s023-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s023-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s023-rollback'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 100 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s023-rollback'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/teaser-card'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-card-s023-rollback' AND l.table_name = 'card_stats'
   AND l.column_name IN ('card_description')
   AND EXISTS (SELECT 1 FROM card_stats t
                WHERE t.site_id::text = l.row_pk AND CASE l.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM l.new_value::character varying
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
